function handlePointerUp(e) {
  const isIgnored = e.composedPath().some(el =>
    el instanceof Element && el.matches(".always-on")
  );

  if (isIgnored) return;

  api.updatePlcmt(1);
  main.querySelector(".cnx-content-wrapper").removeEventListener("pointerup",handlePointerUp);
}


